import json,math
from pathlib import Path
R=json.load(open('atmospheric_fits.json'));Path('models').mkdir(exist_ok=True)
labels={'linear':'LinearResistance','series':'SeriesResistance','power':'PowerOutlet','choked':'ChokedOrifice'}
x='Max(0, Min(1, 1-valve/vfull))';cv=f'({x}/({x}+k))**m';z='(p-patm)'

def param(name,value,unit,typ,desc,eq=None):
 d=dict(name=name,value=float(value),unit=unit,type=typ,description=desc)
 if eq is not None:d['equation']=eq
 return d

def starts_text(r):
 names={0:('a','bar/(s*(l/min))'),1:('c','1/s' if r['name'] in ['linear','power','choked'] else 'bar/s'),2:('m','dimensionless'),3:('k','dimensionless'),5:('lam','1/s') if r['name']=='series' else ('eps','bar'),6:('nu','dimensionless')}
 return ', '.join(f'`{names[i][0]} = {r["start"][i]:.16g}` '+names[i][1] for i in r['active'])

common_family='A one-state grey-box isothermal gas mass-balance model: the inlet term increases stored gas mass and the outlet term removes it. Only effective gains, rather than temperature and volume separately, are identifiable. The ideal-gas storage balance is assumed, not inferred from these data. Grey-box identification reference: Ljung, System Identification: Theory for the User, second edition (1999), cited from memory and not source-checked.'
common_interp='`p` is absolute headspace pressure in bar; `valve` is outlet closure in percent; `flow` is the logged inlet flow in l/min; `dp` is the modeled pressure derivative in bar/s. `a` is the fitted positive inlet conversion gain. `a*flow` is inlet pressurization. `patm = 1` bar is the fixed approximate atmospheric pressure, not a measured atmospheric calibration. `vfull = 100` percent is the declared full-closure position. The clipped opening `Max(0, Min(1, 1-valve/vfull))` is dimensionless. `k` is a positive dimensionless opening scale and `m` a positive dimensionless curvature exponent. The monotone saturating characteristic `('+x+'/('+x+'+k))**m` represents an effective valve conductance, including the outlet plumbing; it is an empirical calibration law, not a measured geometric area. Clipping prevents unphysical conductance when an input is outside its declared range.'
requirements='R1: the flow derivative is `a > 0`, so increasing inlet flow always increases `dp`. R2: on the intended pressurized operating domain `p >= patm`, closing the valve reduces outlet conductance and therefore cannot reduce `dp`. Below atmospheric pressure, ambient backflow restores pressure; closing the valve then reduces that restoration, so R2 cannot hold globally there for this bidirectional-flow model. This is an explicit qualification, not a claimed global monotonicity guarantee. R3: with `flow = 0` and `valve < vfull`, the unique equilibrium is exactly `p = patm = 1` bar. R4: for these same inputs, `dp` has the opposite sign to `p-patm`, giving continuous-time relaxation from either side. R5: at `valve = vfull`, outlet conductance is zero and `dp = a*flow >= 0` for nonnegative supplied flow. No leakage at full closure is assumed; none is identified from the logged range.'
common_limits='No measured headspace temperature, independently calibrated atmospheric pressure, valve geometry, or standard-flow reference conditions were available. Therefore fitted gains do not separately determine tank volume, temperature, or discharge area. The one-state structure omits bubble residence time, controller lag, valve hysteresis, and sensor dynamics. Both trajectories were used in the final fit, so full-trajectory errors are in-sample diagnostics, not test scores. The suffix checks were not used for parameter estimation at that stage, but were inspected during structure selection, so they are not untouched confirmatory tests. At very large pressure departures, negative absolute pressures, altered water level, or different hardware the model is not established. The data do not cover perfectly sealed operation, exactly zero flow at steady state, or all combinations of pressure and valve opening. '
for r in R:
 fam=r['name'];a,c,m,k,pa,e,n=r['t'];pars=[param('a',a,'bar/(s*(l/min))','fitted','Positive inlet mass-flow-to-pressure conversion gain, fitted jointly with the other free parameters by the pressure-rollout least-squares stages described in estimation.'),param('c',c,'bar/s' if fam=='series' else '1/s','fitted','Positive outlet pressure-rate scale, fitted jointly by the pressure-rollout criterion. Its units depend on the explicitly normalized outlet law.'),param('m',m,'-','fitted','Curvature exponent of the effective monotone valve conductance, fitted jointly by the pressure-rollout criterion.'),param('k',k,'-','fitted','Opening scale of the saturating valve characteristic, fitted jointly by the pressure-rollout criterion.'),param('patm',1,'bar','fixed','Approximate absolute atmospheric equilibrium from TASK.md; fixed rather than using an empirical intercept so that zero-inlet equilibrium remains exactly atmospheric.'),param('vfull',100,'%','fixed','Full closure is defined by TASK.md as `valve = 100` percent; used to normalize and clip the opening.')]
 criterion='Sum of squared free-running pressure errors in bar squared, excluding the initial row of each simulated segment. This matches the scored state and discourages long-horizon drift; the filtered `dp` column is not a final fitting target.'
 interp=common_interp
 origin='Physical reasoning supplied the one-state gas inventory balance, a positive term linear in inlet flow, atmospheric pressure as zero outlet driving pressure, and zero outlet conductance at full closure. A deterministic manual structure comparison, not symbolic regression, supplied the saturating opening law. Derivative-target nonlinear least-squares fits initialized the pressure-rollout fits; valve power, exponential, logistic, saturating and series-restriction characteristics were compared. Saturating conductance was retained because it improved pressure prediction without a high-dimensional calibration curve. '
 limit=common_limits
 if fam=='linear':
  expr=f'a*flow-c*{cv}*{z}'
  family=common_family+' The outlet is a linear pneumatic-resistance/Newtonian relaxation law, with input-dependent relaxation rate.'
  interp+=' The term `c*('+x+'/('+x+'+k))**m*(p-patm)` is linear pressure-driven outlet relaxation. `c` has units of inverse seconds. This is a local small-pressure-departure resistance approximation.'
  origin+='This was the baseline family stated before fitting. It was retained as an interpretable low-pressure reference, not because it matched the full data best; nonlinear outlet laws were substantially more accurate.'
  limit+='The linear pressure-flow approximation is poor over the largest observed overpressures; its higher simulation error is evidence against using it as the default process model. '
  slope=c*(1/(1+k))**m
 elif fam=='series':
  lam=r['fit_t'][5];pars.extend([param('pref',1,'bar','fixed','Reference pressure unit, one bar; makes normalized pressure drop dimensionless without changing numerical values.'),param('lam',lam,'1/s','fitted','Maximum open-valve relaxation slope, jointly fitted with an upper bound of `lam <= 0.5` per second to keep the required five-second RK4 step inside its negative-real-axis stability region.'),param('eps',e,'-','tied','Dimensionless linear-resistance scale. Tied so that the maximum relaxation slope at atmospheric pressure and full opening is `lam`.', 'c*(1/(1+k))**m/(pref*lam)')])
  expr=f'a*flow-c*{cv}*2*({z}/pref)/(eps+sqrt(eps**2+4*Abs({z}/pref)))'
  family=common_family+' The outlet law is the signed inverse of a linear-plus-quadratic pressure-flow resistance (a Darcy-Forchheimer-type constitutive analogy; no porous medium is claimed). The law continuously joins viscous-like linear flow and inertia-dominated square-root flow.'
  interp+=' `pref = 1` bar normalizes the pressure drop. `eps` is the dimensionless linear-resistance scale. The normalized outlet function `2*((p-patm)/pref)/(eps+sqrt(eps**2+4*Abs((p-patm)/pref)))` solves a linear-plus-quadratic resistance relation. Its sign allows ambient backflow below atmospheric pressure. `c` has units bar/s. `lam` is the fitted limiting open-valve relaxation rate; `eps = c*(1/(1+k))**m/(pref*lam)` ties the resistance scale to that rate.'
  origin+='The raw signed square-root law was regularized to avoid a singular slope at atmospheric pressure. Residuals favored a nonlinear outlet pressure law, and a linear-plus-quadratic resistance inversion provided a physically defensible smooth transition. An unconstrained series fit was too stiff near atmospheric pressure for the prescribed RK4 step, motivating the limiting-slope parameterization. The equilibrium was finally fixed at atmospheric pressure instead of estimating a pressure offset.'
  limit+='A single valve multiplier assumes separability of valve conductance and pressure dependence. It cannot represent pressure-dependent valve deformation or sonic choking. The stability constraint is active, so the low-pressure time constant is partly imposed by numerical admissibility rather than uniquely measured. '
  slope=lam
 elif fam=='power':
  pars.extend([param('pref',1,'bar','fixed','Reference pressure unit, one bar, used for dimensional consistency of a continuously fitted pressure exponent.'),param('eps',e,'bar','fitted','Positive pressure-drop regularization scale, fitted jointly; gives a finite slope at atmospheric pressure.'),param('nu',n,'-','fitted','Empirical pressure-drop exponent, jointly fitted between the specified sublinear and linear limits; not claimed to uniquely identify a flow regime.')])
  expr=f'a*flow-c*{cv}*{z}*(({z}**2+eps**2)/pref**2)**((nu-1)/2)'
  family=common_family+' The outlet is a regularized signed power-law pressure-flow constitutive relation. It is an empirical interpolation between sublinear orifice-like and linear resistance behavior, rather than an exact compressible-flow formula.'
  interp+=' `pref = 1` bar is the reference pressure unit. `eps` is the positive regularization pressure and `nu` the dimensionless fitted pressure exponent. The outlet function `(p-patm)*(((p-patm)**2+eps**2)/pref**2)**((nu-1)/2)` has a finite linear slope near atmospheric pressure and a signed power-law dependence at larger departures. `c` has units inverse seconds because this function has units bar. The sublinear exponent describes mathematical curvature; it is not independent evidence of a particular valve-flow regime.'
  origin+='The regularized square-root and series-resistance fits left pressure- and closure-dependent residuals. A fitted pressure exponent was tried to allow the data to choose curvature instead of fixing it at a square root. This was a manual constitutive extension, not an automated symbolic search. Flow-quadratic extensions collapsed toward zero gain, and a monotone valve calibration curve did not reliably improve held-out suffix predictions, so neither was retained. The equilibrium was fixed at atmospheric pressure and a slope penalty was added for numerical safety.'
  slope=c*(1/(1+k))**m*(e**2)**((n-1)/2)
  criterion+=' A one-sided residual with weight `100` bar*s penalizes a maximum open-valve relaxation slope above `0.5` per second; the final fit is essentially at that boundary.'
  limit+='The exponent and regularization are phenomenological, and can compensate for unmodeled valve characteristics or filtering. They should not be extrapolated to sonic choking or large changes of pressure or temperature. '
 else:
  gamma=1.4;rc=(2/(gamma+1))**(gamma/(gamma-1))
  pars.extend([param('eps',e,'bar','fitted','Near-equilibrium pressure smoothing scale, jointly fitted; damps the singular ideal-orifice slope.'),param('gamma',gamma,'-','fixed','Assumed ratio of specific heats for ideal air near room temperature; the standard diatomic-gas value, not estimated from this experiment.'),param('rcrit',rc,'-','tied','Critical downstream/upstream pressure ratio from the assumed isentropic nozzle law.', '(2/(gamma+1))**(gamma/(gamma-1))'),param('pfloor',.01,'bar','fixed','Positive lower downstream pressure floor chosen only to avoid invalid fractional pressure-ratio powers outside physical positive-pressure operation; it is inactive in the observed pressure range.')])
  ratio='Max(Max(Min(p,patm),pfloor)/Max(p,patm),rcrit)'
  hh=f'Max(p,patm)*sqrt(2*gamma/(gamma-1)*Max({ratio}**(2/gamma)-{ratio}**((gamma+1)/gamma),0))*{z}/sqrt({z}**2+eps**2)'
  expr=f'a*flow-c*{cv}*{hh}'
  family=common_family+' The outlet uses the standard isentropic compressible-orifice pressure-ratio function with sonic limiting, multiplied by a smooth near-equilibrium correction. Reference: NASA Glenn Research Center, Mass Flow Rate Equations, cited from memory; attempted web retrieval returned no source content, so it was not verified during this run.'
  interp+=' `gamma = 1.4` is the assumed ideal-air heat-capacity ratio. `rcrit = (2/(gamma+1))**(gamma/(gamma-1))` is the dimensionless critical pressure ratio. `Max(p,patm)` is upstream absolute pressure and `Max(Min(p,patm),pfloor)` is downstream absolute pressure. The pressure ratio is clipped below at `rcrit` to represent choking. The ideal compressible outlet factor is multiplied by `(p-patm)/sqrt((p-patm)**2+eps**2)` to give its direction and suppress its singular near-equilibrium slope. This correction is empirical regularization, not a derived isentropic-flow property. `c` has units inverse seconds and absorbs effective discharge area and storage capacity. `pfloor = 0.01` bar is a numerical domain guard, not a measured pressure.'
  interp+=' The complete outlet pressure factor is `'+hh+'`.'
  origin+='Compressible outlet flow was listed before fitting because measured pressure approaches twice atmospheric pressure. A critical pressure-ratio cap came from gas-flow physics rather than a fitted threshold. The smoothing factor was introduced to make an ideal orifice usable near atmospheric pressure. A numerical slope penalty was added after unconstrained parameters gave excessive low-pressure stiffness for the prescribed integration step.'
  criterion+=' A vector of one-sided slope residuals, each with weight `100` bar*s, penalizes open-valve relaxation slopes above `0.48` per second on a pressure grid around atmospheric pressure. The grid has `120` points below and `180` points above atmospheric pressure, as specified in `fit_stable.py`; it is a numerical safety check, not extra measured data.'
  limit+='The outlet is not known to be an ideal nozzle. Heat exchange, moisture, distributed line loss, and valve geometry may change the ideal pressure-ratio relation. Data close to the sonic threshold do not establish choking independently. The numerical slope penalty samples a finite grid and is not a global stability proof. '
  slope=None
 suffix=r['suffix_metrics'];full=r['full_metrics']
 diagnostics=f'For this candidate, final full-trajectory RK4 pressure RMSE was `{full["train"]:.8g}` bar on `data/train.csv` and `{full["val"]:.8g}` bar on `data/val.csv`. Prefix-fitted, independently initialized suffix RMSE was `{suffix["train"]:.8g}` bar on training-file rows `1000:1452` (zero-based) and `{suffix["val"]:.8g}` bar on validation-file rows `1000:1454` (zero-based). '
 if slope is not None:diagnostics+=f'The maximum full-opening pressure relaxation slope of this fitted law is `{slope:.8g}` per second. '
 method='Bound-constrained nonlinear least squares with the trust-region reflective algorithm, `scipy.optimize.least_squares`, using finite-difference Jacobians and `x_scale = "jac"`. This method accommodates nonlinear constitutive parameters and sign constraints; direct ordinary least squares would not minimize pressure-rollout error. Deterministic warm starting used the preceding physically matched fits, with starting values '+starts_text(r)+'. These are numerical starting points taken from `pooled_fits.json` or `stable_fits.json`, not fixed final coefficients. All free parameters of this candidate were fitted together first to both independent trajectory prefixes, then jointly refitted to both full trajectories, starting at that prefix solution. The prefix stage used '+str(r['prefix_nfev'])+' objective evaluations and the full stage used '+str(r['full_nfev'])+' objective evaluations as reported by SciPy; all stages used at most `240` evaluations, `ftol = 1e-9`, and `xtol = 1e-9`. No random search or stochastic sampling was used, so no seed applies. Bounds and every starting value are recorded in `atmospheric_fits.json` and implemented in the reproduction script. Each simulation uses classical RK4 with a step of `5` s, the current row inputs held constant, and only the segment first pressure as an initial condition; later measured pressures never reset the simulation. '
 if fam=='series':method+='`eps` is computed from the fitted `c`, `m`, `k`, and `lam`, not estimated independently. '
 if fam=='choked':method+='`rcrit` is computed from fixed `gamma`, not fitted. '
 obj=dict(expressions={'dp':expr},parameters=pars,estimation=dict(criterion=criterion,data='Final fit: all `1452` rows of `data/train.csv` and all `1454` rows of `data/val.csv`, treated as separate trajectories. Earlier selection fit: first `1000` rows of each file; later rows were excluded at that stage to permit independently initialized contiguous-suffix checks. The validation file was deliberately allowed into final estimation after structure comparison to use both available experiments. '+diagnostics,method=method,script='fit_atmospheric.py'),discussion=dict(family=family,interpretation=interp,origin=origin,limitations=limit+requirements))
 json.dump(obj,open('models/'+labels[fam]+'.json','w'),indent=2)
json.dump(dict(order=['PowerOutlet','ChokedOrifice','SeriesResistance','LinearResistance'],recommended='PowerOutlet',reason='`PowerOutlet` combines the lowest final pooled pressure-rollout error among these atmosphere-anchored candidates with a finite near-equilibrium slope and exactly atmospheric zero-flow equilibrium. Its final RMSE is `0.024786824` bar on `data/train.csv` and `0.037505993` bar on `data/val.csv`; these are in-sample after pooled refitting, not test results. The compressible candidate has the better validation-file suffix result but the worse final pooled fit and assumes ideal nozzle behavior not established by the data. The series model is a more directly interpretable alternative with slightly worse pressure accuracy. The linear candidate is retained only as a transparent small-overpressure baseline. Selection also considered physical monotonicity in the pressurized domain and the required five-second RK4 stability, not derivative error alone.'),open('models/pool.json','w'),indent=2)
